  "rules": [
    {
      "level": "API level: checked on every request before anything is stored",
      "items": [
        "Every download checks on the server that the order is paid.",
        "The price is set by DocFlow's server, from configuration.",
        "DocFlow passes the person's own token to services when they are present, and a delegated token for them when not, so every service's ownership checks apply.",
        "Service events are verified and processed once."
      ]
    },
    {
      "level": "Schema level: enforced by the database, whatever the code does",
      "items": [
        "A document's status always has the parts it needs (a job once extracting, a task once in review, an order once paid)."
      ]
    },
    {
      "level": "Data model level: business rules the service guarantees",
      "items": [
        "DocFlow stores IDs of other services' records, never their data.",
        "Every document is reviewed, even when nothing is flagged.",
        "Results are built only from a completed review, always from Review's latest values."
      ]
    }
  ],
